+    .outlook-panel h2 { margin: 0; font-size: clamp(1.8rem, 4vw, 2.8rem); letter-spacing: -.055em; line-height: 1.08; }
+    .outlook-panel p { margin: 0 0 .85rem; color: var(--page); opacity: .84; }
+    .outlook-panel p:last-child { margin-bottom: 0; }
